 page.set_viewport_size({'width':1280,'height':900});setup();page.evaluate('c.begin(base)');check(page.evaluate('''()=>{const node=document.createElement('section');node.textContent='새 위젯';return c.addWidget({id:'widget-new',type:'briefing',source:{},visible:true,locked:false,desktop:{x:0,y:1000,w:300,h:220,size:'s'},mobile:{x:0,y:1000,w:360,h:220,size:'s'}},node,'새 위젯')}'''),'new instance added');check(page.locator('[data-dashboard-widget=widget-new]').count()==1,'new instance mounted');check(page.evaluate("c.layout.widgets.length===4&&c.current('widget-b').locked"),'add preserves existing layout and locks');check(not page.evaluate("c.addWidget({...c.current('widget-new')},document.createElement('div'),'duplicate')"),'duplicate instance rejected');check(not page.evaluate("MoaDashboardCanvas.valid({...base,widgets:[{...base.widgets[0],id:'unsafe\"selector'}]})"),'unsafe CSS selector id rejected');check(not page.evaluate("MoaDashboardCanvas.valid({...base,widgets:[{...base.widgets[0],source:{url:'https://example.com'}}]})"),'unknown source fields rejected');page.keyboard.press('Escape')
